CREATE DATABASE IF NOT EXISTS manuz_workspace CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE manuz_workspace;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(120) NOT NULL, role ENUM('admin','teacher','student','staff') NOT NULL DEFAULT 'student', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS conversations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, title VARCHAR(180) NOT NULL DEFAULT 'Nova conversa', provider VARCHAR(80) NOT NULL DEFAULT 'lmstudio', model VARCHAR(190) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, conversation_id BIGINT UNSIGNED NOT NULL, role ENUM('system','user','assistant','tool') NOT NULL, content LONGTEXT NOT NULL, tool_call_id VARCHAR(190) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(conversation_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS agent_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, conversation_id BIGINT UNSIGNED NULL, event_type VARCHAR(60) NOT NULL, tool_name VARCHAR(120) NULL, payload JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id), INDEX(conversation_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS staging_proposals (id CHAR(32) PRIMARY KEY, user_id BIGINT UNSIGNED NULL, status ENUM('pending','approved','rejected','applied') NOT NULL DEFAULT 'pending', expires_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS staging_files (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, proposal_id CHAR(32) NOT NULL, relative_path VARCHAR(500) NOT NULL, operation ENUM('create','replace','delete') NOT NULL, content LONGTEXT NULL, original_hash CHAR(64) NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS school_registry (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, enrollment_code VARCHAR(80) NOT NULL UNIQUE, full_name VARCHAR(160) NOT NULL, email VARCHAR(190) NULL, person_type ENUM('student','teacher','staff','management','other') NOT NULL, status ENUM('pre_registered','invited','active','inactive') NOT NULL DEFAULT 'pre_registered', user_id BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(email), INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, relative_path VARCHAR(500) NOT NULL, description TEXT NULL, status ENUM('active','archived') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NULL, status ENUM('todo','doing','done','blocked') NOT NULL DEFAULT 'todo', priority ENUM('low','normal','high') NOT NULL DEFAULT 'normal', due_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(project_id), INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_files (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, relative_path VARCHAR(500) NOT NULL, label VARCHAR(160) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY project_file(project_id,relative_path)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_skills (project_id BIGINT UNSIGNED NOT NULL, skill_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(project_id,skill_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skills (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description TEXT NOT NULL, definition JSON NOT NULL, enabled TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS plugins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, version VARCHAR(40) NOT NULL DEFAULT '1.0.0', description TEXT NOT NULL, manifest JSON NOT NULL, enabled TINYINT(1) NOT NULL DEFAULT 0, trusted TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS action_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, session_id VARCHAR(128) NULL, action VARCHAR(120) NOT NULL, target VARCHAR(500) NULL, details JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id), INDEX(session_id), INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS external_integrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, kind ENUM('rest','graphql','ftp','mysql','postgresql','web_search','automation') NOT NULL DEFAULT 'rest', base_url VARCHAR(500) NULL, auth_type ENUM('none','bearer_env','header_env','basic_env','ssh_key_file') NOT NULL DEFAULT 'none', credential_ref VARCHAR(190) NULL, test_endpoint VARCHAR(500) NULL, config_json JSON NULL, enabled TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(user_id), UNIQUE KEY user_integration(user_id,name)) ENGINE=InnoDB;
